import { brotliDecompressSync } from "node:zlib";
import { createHash } from "node:crypto";
import { mkdirSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
const parts = [0,1,2,3,4,5].map(i => Bun.env["ARCANALFG_ASSET_" + i] || "");
if (parts.some(p => !p)) throw new Error("ArcanaLFG source bundle is incomplete");
parts[4] = "" + parts[4].slice(750);
const encoded = parts.join("");
const checksum = createHash("sha256").update(encoded).digest("hex").slice(0,20);
console.log("ArcanaLFG source checksum", checksum);
if (checksum !== "34f2bd47d26e225766b3") throw new Error("ArcanaLFG source integrity mismatch");
const assets = JSON.parse(brotliDecompressSync(Buffer.from(encoded, "base64")).toString("utf8"));
const root = "/tmp/arcanalfg-site-v010";
for (const [filename, contents] of Object.entries(assets)) {
  const relative = filename === "server.js" ? "server.mjs" : filename;
  const target = join(root, relative);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, String(contents));
}

// ARCANA_LFG_BRANDING_V2
const brandPatch=JSON.parse(brotliDecompressSync(Buffer.from("","base64")).toString("utf8"));
const idxFile=join(root,"public/index.html");
let siteMarkup=await Bun.file(idxFile).text();
for(const [from,to] of brandPatch.replacements){if(!siteMarkup.includes(from))throw new Error("ArcanaLFG expected markup missing");siteMarkup=siteMarkup.replace(from,to)}
writeFileSync(idxFile,siteMarkup);
for(const [fileName,extra] of [["styles.css",brandPatch.css],["app.js",brandPatch.js]]){
 const asset=join(root,"public",fileName);writeFileSync(asset,(await Bun.file(asset).text())+extra);
}
writeFileSync(join(root,"public","zane-mark.webp"),Buffer.from(brandPatch.logo,"base64"));
console.log("ARCANALFG_BRAND_V2",JSON.stringify({replacements:brandPatch.replacements.length,css:brandPatch.css.length,js:brandPatch.js.length,logo:brandPatch.logo.length}));



/* ARCANA_LFG_UNITY_V6_SMALL_BOOTSTRAP */
const unifiedApi="\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport crypto from 'node:crypto';\nconst DIR=process.env.DATA_DIR||'/data';\nconst FILE=path.join(DIR,'raid-plans-v3.json');\nconst classes=['Warrior','Mage','Rogue','Archer','Druid'];\nconst kinds=['scheduled','team'];\nconst states=['open','paused','closed'];\nconst hits=new Map();\nfs.mkdirSync(DIR,{recursive:true});\nfunction fail(message,status=400){const e=new Error(message);e.status=status;throw e;}\nfunction text(x,max=100){return String(x??'').replace(/[\\u0000-\\u001f\\u007f]/g,' ').trim().slice(0,max);}\nfunction num(x,min,max,label){const n=Number(x);if(!Number.isFinite(n)||n<min||n>max)fail('Invalid '+label);return n;}\nfunction read(){try{const x=JSON.parse(fs.readFileSync(FILE,'utf8'));return Array.isArray(x)?x:[];}catch(e){if(e.code==='ENOENT')return [];throw e;}}\nfunction save(plans){const tmp=FILE+'.'+process.pid+'.tmp';fs.writeFileSync(tmp,JSON.stringify(plans),{mode:0o600});fs.renameSync(tmp,FILE);}\nfunction publicPlan(p){const {ownerToken,applications,...rest}=p;return {...rest,applicationsCount:applications.filter(a=>a.status==='pending').length};}\nfunction response(res,status,value){res.writeHead(status,{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'});res.end(JSON.stringify(value));}\nasync function body(req){let size=0,chunks=[];for await(const c of req){size+=c.length;if(size>12000)fail('Request too large',413);chunks.push(c);}try{return JSON.parse(Buffer.concat(chunks).toString('utf8')||'{}');}catch{fail('Invalid JSON');}}\nfunction rate(req,key,limit){const now=Date.now();const id=(String(req.headers['x-forwarded-for']||'').split(',')[0].trim()||req.socket.remoteAddress||'unknown')+':'+key;const a=(hits.get(id)||[]).filter(x=>x>now-3600000);if(a.length>=limit)fail('Too many requests; please try later',429);a.push(now);hits.set(id,a);}\nfunction owner(req,p){const given=String(req.headers['x-owner-token']||'');const actual=String(p.ownerToken||'');if(!given||!actual||given.length!==actual.length||!crypto.timingSafeEqual(Buffer.from(given),Buffer.from(actual)))fail('Owner access required',403);}\nfunction prune(plans){const now=Date.now();const before=plans.length;plans=plans.filter(p=>p.kind==='team'? Date.parse(p.bumpedAt||p.createdAt)>now-31*86400000 : Date.parse(p.startAt)>now-86400000);return {plans,changed:before!==plans.length};}\nfunction compatible(p,b){if(p.status!=='open')fail('This plan is not accepting applications');if(p.members.length>=4)fail('The team is full');const playerClass=text(b.characterClass,20);if(!classes.includes(playerClass))fail('Choose a valid class');const might=num(b.might,0,1e111,'Might');if(might<p.minMight||might>p.maxMight)fail('Might is outside this listing range');if(p.mode==='specific'&&!p.allowedClasses.includes(playerClass))fail('Class is not accepted by this listing');if(p.mode==='unique'&&p.members.some(m=>m.characterClass===playerClass))fail('This class is already taken');return {characterClass:playerClass,might};}\nfunction serializeOwner(p){return {...publicPlan(p),applications:p.applications};}\nexport async function handlePlan(req,res){\n const url=new URL(req.url,'http://localhost');\n if(!url.pathname.startsWith('/api/plans'))return false;\n try{\n  const origin=req.headers.origin;\n  if(origin&&new URL(origin).host!==req.headers.host)fail('Cross-origin requests are not allowed',403);\n  const parts=url.pathname.split('/').filter(Boolean);\n  let {plans,changed}=prune(read());if(changed)save(plans);\n  if(parts.length===2&&req.method==='GET'){\n   return response(res,200,{plans:plans.filter(p=>p.status!=='closed').map(publicPlan)}),true;\n  }\n  if(parts.length===2&&req.method==='POST'){\n   rate(req,'create',20);\n   if(plans.length>=1500)fail('Board currently at capacity',503);\n   const b=await body(req);\n   const kind=text(b.kind,16);if(!kinds.includes(kind))fail('Select scheduled raid or daily team');\n   const leader=text(b.leader,32);if(leader.length<2)fail('Enter a character name');\n   const title=text(b.title,80);if(title.length<3)fail('Enter a clear listing title');\n   const characterClass=text(b.characterClass,20);if(!classes.includes(characterClass))fail('Choose a class');\n   const mode=text(b.mode,16)||'any';if(!['any','specific','unique'].includes(mode))fail('Invalid class rule');\n   const allowedClasses=Array.isArray(b.allowedClasses)?b.allowedClasses.filter(x=>classes.includes(x)):[];\n   if(mode==='specific'&&!allowedClasses.length)fail('Select at least one eligible class');\n   const might=num(b.might,0,1e111,'leader Might');\n   const minMight=num(b.minMight,0,1e111,'minimum Might');\n   const maxMight=num(b.maxMight,0,1e111,'maximum Might');\n   if(minMight>maxMight)fail('Maximum Might must be at least minimum');\n   const tier=num(b.tier,1,4,'raid tier');\n   const now=Date.now();\n   let startAt=null, time=null,timezone=null,days=[];\n   if(kind==='scheduled'){\n    startAt=new Date(b.startAt).toISOString();const date=Date.parse(startAt);\n    if(date<=now+120000||date>now+90*86400000)fail('Choose a time between 2 minutes and 90 days from now');\n   }else{\n    time=text(b.time,5);if(!/^([01]\\d|2[0-3]):[0-5]\\d$/.test(time))fail('Choose a daily raid time');\n    timezone=text(b.timezone,80);try{new Intl.DateTimeFormat('en-US',{timeZone:timezone});}catch{fail('Invalid time zone');}\n    days=Array.isArray(b.days)?[...new Set(b.days.map(Number).filter(x=>Number.isInteger(x)&&x>=0&&x<=6))]:[];\n    if(!days.length)fail('Choose at least one day');\n   }\n   const plan={id:crypto.randomUUID(),kind,title,leader,guild:text(b.guild,32),tier,characterClass,might,mode,allowedClasses,\n     minMight,maxMight,notes:text(b.notes,500),contact:text(b.contact,80),\n     startAt,time,timezone,days,status:'open',members:[{name:leader,characterClass,might}],\n     applications:[],ownerToken:crypto.randomBytes(32).toString('hex'),createdAt:new Date().toISOString(),bumpedAt:new Date().toISOString()};\n   plans.unshift(plan);save(plans);return response(res,201,{plan:publicPlan(plan),ownerToken:plan.ownerToken}),true;\n  }\n  if(parts.length<3)fail('Not found',404);\n  const p=plans.find(x=>x.id===parts[2]);if(!p)fail('Plan not found or expired',404);\n  if(parts.length===3&&req.method==='GET')return response(res,200,{plan:publicPlan(p)}),true;\n  if(parts[3]==='owner'&&req.method==='GET'){owner(req,p);return response(res,200,{plan:serializeOwner(p)}),true;}\n  if(parts[3]==='application'&&parts[4]&&req.method==='GET'){\n   const a=p.applications.find(x=>x.id===parts[4]);if(!a)fail('Application not found',404);\n   return response(res,200,{status:a.status,listing:p.title,leader:p.leader}),true;\n  }\n  if(parts[3]==='apply'&&req.method==='POST'){\n   rate(req,'apply',60);\n   const b=await body(req);const player=compatible(p,b);\n   const name=text(b.name,32);if(name.length<2)fail('Enter a character name');\n   if(p.members.some(m=>m.name.toLowerCase()===name.toLowerCase())||p.applications.some(a=>a.name.toLowerCase()===name.toLowerCase()&&a.status==='pending'))fail('This character has already joined or applied');\n   if(p.applications.filter(a=>a.status==='pending').length>=40)fail('Too many pending applications');\n   const a={id:crypto.randomUUID(),name,...player,contact:text(b.contact,80),message:text(b.message,200),status:'pending',createdAt:new Date().toISOString()};\n   p.applications.push(a);save(plans);return response(res,201,{applicationId:a.id,status:a.status}),true;\n  }\n  if(parts[3]==='review'&&req.method==='POST'){\n   owner(req,p);const b=await body(req);const a=p.applications.find(x=>x.id===b.applicationId);\n   if(!a||a.status!=='pending')fail('Application no longer pending');\n   if(b.decision!=='accept'&&b.decision!=='decline')fail('Choose accept or decline');\n   if(b.decision==='accept'){\n    compatible(p,a);\n    if(p.members.some(x=>x.name.toLowerCase()===a.name.toLowerCase()))fail('Player already in party');\n    p.members.push({name:a.name,characterClass:a.characterClass,might:a.might});\n   }\n   a.status=b.decision==='accept'?'accepted':'declined';\n   if(p.members.length>=4)p.status='paused';\n   save(plans);return response(res,200,{plan:serializeOwner(p)}),true;\n  }\n  if(parts[3]==='update'&&req.method==='POST'){\n   owner(req,p);const b=await body(req);\n   if(b.action==='bump')p.bumpedAt=new Date().toISOString();\n   else if(b.action==='status'){\n    if(!states.includes(b.status))fail('Invalid listing status');\n    if(b.status==='open'&&p.members.length>=4)fail('Party is already full');\n    p.status=b.status;\n   }else fail('Unknown action');\n   save(plans);return response(res,200,{plan:serializeOwner(p)}),true;\n  }\n  fail('Not found',404);\n }catch(e){response(res,e.status||500,{error:e.status?e.message:'Server error'});if(!e.status)console.error('Planner error',e);return true;}\n}\n";
const apiPath=join(root,"planner-api.mjs");
let apiText=unifiedApi.replaceAll("1e111","999e24").replace("const {ownerToken,applications,...rest}=p;","const {ownerToken,applications,contact,...rest}=p;");
writeFileSync(apiPath,apiText);
const srvPath=join(root,"server.mjs");
let serverCode=await Bun.file(srvPath).text();
if(!serverCode.includes("const srv=http.createServer(serverHandler);"))throw Error("Missing server extension point");
serverCode=serverCode.replace("const MAX_MIGHT = Number.MAX_SAFE_INTEGER;","const MAX_MIGHT = 999e24;");
serverCode=serverCode.replaceAll("Number.isSafeInteger(Number(value))","Number.isFinite(Number(value))");
serverCode=serverCode.replace("const srv=http.createServer(serverHandler);","const { handlePlan } = await import('./planner-api.mjs');\nconst srv=http.createServer((req,res)=>{Promise.resolve(handlePlan(req,res)).then(handled=>{if(!handled)serverHandler(req,res)}).catch(err=>{console.error(err);if(!res.headersSent){res.writeHead(500,{'Content-Type':'application/json'});res.end(JSON.stringify({error:'Server error'}))}else res.end()})});");
writeFileSync(srvPath,serverCode);
